def safe_rel(path: str) -> bool:
    """True when path, after normalising '.' and '..' segments, stays inside its base directory: no absolute paths, no empty path, no escape above the base."""
    ex safe_rel("a.txt") == True
    ex safe_rel("sub/../a.txt") == True
    ex safe_rel("") == False
    ex safe_rel("..") == False
    ex safe_rel("/etc/passwd") == False
    ex safe_rel("sub/../../x") == False
    if path == "" or path.startswith("/"):
        return False
    depth = 0
    for seg in path.split("/"):
        if seg == "" or seg == ".":
            continue
        if seg == "..":
            depth -= 1
            if depth < 0:
                return False
        else:
            depth += 1
    return depth > 0

def read_public(path: str) -> str uses fs:
    """Text of the file at path inside the directory notes, or an empty string. Confines fs to notes with `with fs = fs.sub("notes"):`. A path that leaves notes, a missing file, or an unreadable file gives an empty string."""
    post safe_rel(path) or out == ""
    with fs = fs.sub("notes"):
        if not safe_rel(path):
            return ""
        return fs.read_text(path) else ""
